package kitchen.sink.member.mapper;

import kitchen.sink.member.dto.request.CreateMemberRequest;
import kitchen.sink.member.entity.Member;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;

@Mapper(componentModel = "spring", imports = kitchen.sink.member.util.EmailNormalizer.class)
public interface MemberMapper {

    /** Builds the entity to store; the id is generated by MongoDB and the email is normalized. */
    @Mapping(target = "id", ignore = true)
    @Mapping(target = "email", expression = "java(EmailNormalizer.normalize(request.email()))")
    Member toEntity(CreateMemberRequest request);
}
